H=Path(__file__).resolve().parent;P=json.loads((H/'parameters-v2.json').read_text());G=P['material_original'];S=json.loads((H/'geometry-report.json').read_text())['shape'];W,V=G['texture_size_px'];Lu=2*np.pi*G['working_mean_U_radius_m'];Lv=S['working_profile_closed_length_m'];du,dv=Lu/W,Lv/V;sigma=(G['working_normal_noise_scale_m']/dv,G['working_normal_noise_scale_m']/du);rng=np.random.default_rng(G['normal_field_seed']);z=gaussian_filter(rng.standard_normal((V,W)).astype(np.float64),sigma,mode='wrap');z*=G['working_height_RMS_m']/z.std();dx=(np.roll(z,-1,1)-np.roll(z,1,1))/(2*du);dy=(np.roll(z,-1,0)-np.roll(z,1,0))/(2*dv);n=np.stack([-dx,dy,np.ones_like(dx)],2);n/=np.linalg.norm(n,axis=2,keepdims=True);pixels=np.uint8(np.clip(np.rint((n*.5+.5)*255),0,255));path=H/'textures/gasket-original-normal-v2.png';Image.fromarray(pixels,'RGB').save(path);report={'generator':'Original wrap Gaussian field, seed591002; finite central derivatives, PNG rows down vs BlenderVup accounted','path':str(path.relative_to(H)),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'size_px':[W,V],'working_height_RMS_m':float(z.std()),'working_correlation_sigma_m':G['working_normal_noise_scale_m'],'working_U_metric_length_m':float(Lu),'working_V_metric_length_m':float(Lv),'gaussian_sigma_pixels':list(sigma),'u8_min':pixels.reshape(-1,3).min(0).tolist(),'u8_max':pixels.reshape(-1,3).max(0).tolist(),'u8_std':pixels.reshape(-1,3).std(0).tolist(),'metric_limit':'U uses mean working radius14.5mm versus actual candidate13..16mm, so local U density differs by about±12%. V is candidate section arclength. Neither physical texture/height nor exact chemistry is measured. Normalmap only, no geometric displacement or contact claim.','photo_pixels_used':False,'crossed_sinusoidal_signal':False,'art_accepted':False};(H/'normal-generation-v2.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
